INSERT INTO sys_permission(id,permission_code,permission_name,resource_type,client_type,parent_id,sort_order,status,description) SELECT base.max_id+ROW_NUMBER() OVER(ORDER BY m.id),m.code,m.name,'BUTTON','WEB',pp.id,m.sort_order,'ENABLED','管理功能独立操作权限' FROM sys_menu m JOIN sys_menu parent ON parent.id=m.parent_id LEFT JOIN sys_permission pp ON pp.permission_code=parent.code CROSS JOIN(SELECT COALESCE(MAX(id),0) max_id FROM sys_permission) base WHERE m.code IN('IAM_ROLE_UPDATE','IAM_ROLE_DELETE','IAM_ROLE_STATUS_CHANGE','ORG_TYPE_UPDATE','ORG_TYPE_DELETE','ORG_TYPE_STATUS_CHANGE','IAM_USER_STATUS_CHANGE','iam.role-edit.cancel','organizations.type-edit.cancel') AND NOT EXISTS(SELECT 1 FROM sys_permission p WHERE p.permission_code=m.code);
INSERT INTO sys_role_permission(id,role_id,permission_id,effect) SELECT base.max_id+ROW_NUMBER() OVER(ORDER BY rp.role_id),rp.role_id,p.id,rp.effect FROM sys_role_permission rp JOIN sys_permission old ON old.id=rp.permission_id AND old.permission_code='IAM_ROLE_CREATE' JOIN sys_permission p ON p.permission_code='IAM_ROLE_UPDATE' CROSS JOIN(SELECT COALESCE(MAX(id),0) max_id FROM sys_role_permission) base WHERE NOT EXISTS(SELECT 1 FROM sys_role_permission existing WHERE existing.role_id=rp.role_id AND existing.permission_id=p.id);
INSERT INTO sys_user_permission(id,user_id,permission_id,effect) SELECT base.max_id+ROW_NUMBER() OVER(ORDER BY up.user_id),up.user_id,p.id,up.effect FROM sys_user_permission up JOIN sys_permission old ON old.id=up.permission_id AND old.permission_code='IAM_ROLE_CREATE' JOIN sys_permission p ON p.permission_code='IAM_ROLE_UPDATE' CROSS JOIN(SELECT COALESCE(MAX(id),0) max_id FROM sys_user_permission) base WHERE NOT EXISTS(SELECT 1 FROM sys_user_permission existing WHERE existing.user_id=up.user_id AND existing.permission_id=p.id);
