-- Management lifecycle permissions and audit extension. Preserve existing ALLOW/DENY decisions.
UPDATE sys_menu SET status='DISABLED',grantable=0,version=version+1 WHERE code IN('users.status.enabled','users.status.disabled','users.status.locked');
UPDATE sys_permission SET status='DISABLED' WHERE permission_code IN('users.status.enabled','users.status.disabled','users.status.locked');
ALTER TABLE sys_iam_change_audit DROP CONSTRAINT ck_sys_iam_change_audit_event;
ALTER TABLE sys_iam_change_audit ADD CONSTRAINT ck_sys_iam_change_audit_event CHECK(event_type IN('USER_CREATE','USER_PROFILE_CHANGE','USER_PASSWORD_RESET','USER_STATUS_CHANGE','USER_ORGANIZATION_ASSOCIATE','USER_ROLE_ASSIGN','ROLE_CREATE','PERMISSION_CREATE','ROLE_PERMISSION_CONFIGURE','ROLE_PERMISSION_REMOVE','USER_PERMISSION_CONFIGURE','USER_PERMISSION_REMOVE','ROLE_DATA_SCOPE_ADD','ORGANIZATION_ADMIN_ASSIGN','MENU_CREATE','MENU_UPDATE','MENU_REORDER','ORGANIZATION_TREE_REORDER','ORGANIZATION_TREE_MOVE','MENU_DELETE','USER_ORGANIZATION_DISSOCIATE','ORGANIZATION_ADMIN_REVOKE','USER_ROLE_REMOVE','ROLE_UPDATE','ROLE_DELETE','ROLE_STATUS_CHANGE','ORGANIZATION_TYPE_UPDATE','ORGANIZATION_TYPE_DELETE','ORGANIZATION_TYPE_STATUS_CHANGE'));
ALTER TABLE sys_iam_change_audit DROP CONSTRAINT ck_sys_iam_change_audit_target;
ALTER TABLE sys_iam_change_audit ADD CONSTRAINT ck_sys_iam_change_audit_target CHECK(target_type IN('USER','ROLE','PERMISSION','ROLE_PERMISSION','USER_PERMISSION','ROLE_DATA_SCOPE','ORGANIZATION_ADMIN','USER_ORGANIZATION','USER_ROLE','MENU','ORGANIZATION_TREE','ORGANIZATION_TYPE'));
